using System.Collections.Generic;public class Solution{Dictionary<char,string>m=new();HashSet<string>u=new();bool F(string p,int i,string s,int j){if(i==p.Length||j==s.Length)return i==p.Length&&j==s.Length;char c=p[i];if(m.ContainsKey(c)){string x=m[c];return s.Substring(j).StartsWith(x)&&F(p,i+1,s,j+x.Length);}for(int e=j+1;e<=s.Length;e++){string x=s.Substring(j,e-j);if(u.Contains(x))continue;m[c]=x;u.Add(x);if(F(p,i+1,s,e))return true;u.Remove(x);m.Remove(c);}return false;}public bool WordPatternMatch(string p,string s)=>F(p,0,s,0);}
